body.script:
(function(w,d){
  if(!w.setSelectValue){
    w.setSelectValue=function(id,value){
      var x=d.getElementById(id);
      if(!x)return false;
      var val=String(value==null?'':value);
      try{
        if(x.tagName && String(x.tagName).toLowerCase()==='select'){
          var found=false;
          var opts=x.options||[];
          for(var i=0;i<opts.length;i++){if(String(opts[i].value)===val){found=true;break;}}
          if(!found && val!==''){
            var opt=d.createElement('option');
            opt.value=val; opt.textContent=val; x.appendChild(opt);
          }
        }
        x.value=val;
        try{x.dispatchEvent(new Event('change',{bubbles:true}));}catch(e){}
        return true;
      }catch(err){try{x.value=val;}catch(e){} return false;}
    };
  }
})(window,document);

const APP_FRONTEND={name:'SI-PRAKERIN SMK',version:'1.0.0',developer:'Ifti Media Computindo',defaultApiUrl:'https://script.google.com/macros/s/AKfycbxm6SQsYJD3yqxatl6mJQK4EKHGQoFx54JG-bKzk5f_Fb7BFV4OVuhoZ7e5qI8C39J1/exec'};
const STORAGE_KEYS={apiUrl:'siprakerin_api_url',token:'siprakerin_token',user:'siprakerin_user'};
const IMAGE_ACCEPT='image/*,.jpg,.jpeg,.png,.webp,.gif,.svg,.ico,.bmp,.avif,.heic,.heif';
const ROLE_AVATAR={super_admin:'🛡',admin:'🧑‍💼',humas:'🤝',kurikulum:'📚',kepala_sekolah:'🏫',guru:'👨‍🏫',wali_kelas:'👥',siswa:'🎒',pembimbing_dudi:'🏭',orang_tua:'👨‍👩‍👧',industri:'🏢'};
const MENU_CATALOG={dashboard:{label:'Dashboard',icon:'🏠',title:'Dashboard',text:'Ringkasan data Prakerin.'},settings:{label:'Pengaturan',icon:'⚙️',title:'Pengaturan Sistem',text:'Kelola konfigurasi sistem.'},users:{label:'User',icon:'👤',title:'Manajemen User',text:'Kelola akun pengguna.'},majors:{label:'Jurusan',icon:'🏫',title:'Data Jurusan',text:'Kelola kompetensi keahlian.'},classes:{label:'Kelas',icon:'🏷',title:'Data Kelas',text:'Kelola data kelas.'},students:{label:'Siswa',icon:'🎒',title:'Data Siswa',text:'Kelola data siswa.'},teachers:{label:'Guru',icon:'👨‍🏫',title:'Data Guru',text:'Kelola data guru.'},industries:{label:'DU/DI',icon:'🏢',title:'Data DU/DI',text:'Kelola dunia usaha dan industri.'},industry_mentors:{label:'Pembimbing DU/DI',icon:'🧑‍🔧',title:'Pembimbing Dunia Usaha',text:'Kelola pembimbing dunia usaha/industri.'},periods:{label:'Periode',icon:'📅',title:'Periode Prakerin',text:'Kelola periode.'},teacher_industry_assignments:{label:'Penugasan Guru',icon:'🧭',title:'Penugasan Guru ke DU/DI',text:'Atur guru pembimbing.'},placements:{label:'Penempatan',icon:'📍',title:'Penempatan Siswa',text:'Kelola penempatan siswa.'},my_placement:{label:'Prakerin Saya',icon:'📍',title:'Prakerin Saya',text:'Lihat penempatan saya.'},my_students:{label:'Siswa Bimbingan',icon:'🎒',title:'Siswa Bimbingan',text:'Lihat siswa bimbingan.'},my_industries:{label:'DU/DI Bimbingan',icon:'🏢',title:'DU/DI Bimbingan',text:'Lihat DU/DI bimbingan.'},my_placements:{label:'Penempatan Saya',icon:'📍',title:'Penempatan Guru',text:'Lihat penempatan bimbingan.'},my_class_students:{label:'Siswa Kelas',icon:'👥',title:'Siswa Kelas Saya',text:'Lihat siswa wali kelas.'},industry_students:{label:'Siswa DU/DI',icon:'👥',title:'Siswa DU/DI',text:'Lihat siswa di DU/DI.'},qr_sessions:{label:'Sesi QR',icon:'▣',title:'Sesi QR Presensi',text:'Buat QR Code presensi.'},scan_qr:{label:'Scan QR',icon:'📷',title:'Scan QR Presensi',text:'Scan QR untuk presensi.'},attendance:{label:'Presensi',icon:'✅',title:'Presensi Prakerin',text:'Kelola presensi.'},my_attendance:{label:'Presensi Saya',icon:'✅',title:'Presensi Saya',text:'Riwayat presensi.'},attendance_validation:{label:'Validasi Presensi',icon:'☑️',title:'Validasi Presensi',text:'Validasi kehadiran.'},journals:{label:'Jurnal',icon:'📝',title:'Jurnal Harian',text:'Kelola jurnal.'},my_journals:{label:'Jurnal Saya',icon:'📝',title:'Jurnal Saya',text:'Input jurnal harian.'},journal_validation:{label:'Validasi Jurnal',icon:'🖊',title:'Validasi Jurnal',text:'Validasi jurnal.'},monitoring:{label:'Monitoring',icon:'🚗',title:'Monitoring Guru',text:'Catatan monitoring.'},assessments:{label:'Nilai',icon:'📊',title:'Penilaian Prakerin',text:'Kelola nilai.'},my_assessment:{label:'Nilai Saya',icon:'📊',title:'Nilai Saya',text:'Lihat nilai.'},industry_assessment:{label:'Nilai Industri',icon:'📊',title:'Penilaian Industri',text:'Input nilai industri.'},certificates:{label:'Sertifikat',icon:'🏅',title:'Sertifikat Prakerin',text:'Kelola sertifikat.'},my_certificate:{label:'Sertifikat Saya',icon:'🏅',title:'Sertifikat Saya',text:'Lihat sertifikat saya.'},documents:{label:'Dokumen',icon:'📄',title:'Dokumen',text:'Daftar dokumen.'},reports:{label:'Laporan',icon:'🖨',title:'Laporan dan Cetak',text:'Cetak dokumen.'},uploads:{label:'Upload File',icon:'📤',title:'Upload Gambar dan Dokumen',text:'Upload gambar, foto, dan dokumen ke Google Drive.'},backup:{label:'Backup',icon:'💾',title:'Tools dan Backup',text:'Backup dan import CSV.'},activity_logs:{label:'Log Aktivitas',icon:'🕘',title:'Log Aktivitas',text:'Riwayat aktivitas.'},profile:{label:'Profil',icon:'👤',title:'Profil Saya',text:'Profil pengguna.'}};
const appState={apiUrl:'',token:'',user:null,menuAccess:[],dashboardData:null,currentModule:'',settings:{},branding:{}};try{window.appState=appState;}catch(e){}try{window.appState=appState;}catch(e){}let relationCache={},toastTimer=null,html5QrInstance=null,currentCrudModule='',currentCrudEditId='',currentCrudItems=[],currentReportType='';
document.addEventListener('DOMContentLoaded',initApp);
function initApp(){el('footerYear').textContent=new Date().getFullYear();appState.apiUrl=APP_FRONTEND.defaultApiUrl||localStorage.getItem(STORAGE_KEYS.apiUrl)||'';localStorage.setItem(STORAGE_KEYS.apiUrl,appState.apiUrl);appState.token=localStorage.getItem(STORAGE_KEYS.token)||'';try{appState.user=JSON.parse(localStorage.getItem(STORAGE_KEYS.user)||'null')}catch(e){}el('apiUrlInput').value=appState.apiUrl;bindEvents();loadAppBranding();appState.token?verifySession():showLoginPage()}
function bindEvents(){el('loginForm').addEventListener('submit',e=>{e.preventDefault();login()});el('logoutBtn').addEventListener('click',logout);el('refreshSessionBtn').addEventListener('click',()=>loadDashboardStats(true));el('moduleBackBtn').addEventListener('click',showDashboardPage);el('seeAllMenuBtn').addEventListener('click',()=>openAllMenuModule());el('bottomHome').addEventListener('click',showDashboardPage);el('bottomData').addEventListener('click',()=>openAllMenuModule('data'));el('bottomScan').addEventListener('click',()=>appState.menuAccess.includes('scan_qr')?openModule('scan_qr'):(appState.menuAccess.includes('qr_sessions')?openModule('qr_sessions'):showToast('Menu QR tidak tersedia.','warning')));el('bottomActivity').addEventListener('click',()=>openAllMenuModule('activity'));el('bottomProfile').addEventListener('click',openProfileModule)}
function el(id){return document.getElementById(id)}
async function apiRequest(payload){const apiUrl=appState.apiUrl||localStorage.getItem(STORAGE_KEYS.apiUrl)||'';if(!apiUrl)throw new Error('URL Apps Script belum diisi.');const res=await fetch(apiUrl,{method:'POST',mode:'cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload||{})});const json=await res.json();if(!json.success)throw new Error(json.message||'Request gagal.');return json.data}
async function login(){
  try{
    const apiUrl=(el('apiUrlInput').value.trim()||APP_FRONTEND.defaultApiUrl),username=el('usernameInput').value.trim(),password=el('passwordInput').value.trim();
    if(!apiUrl||!username||!password)return showToast('URL, username, dan password wajib diisi.','error');
    showLoading(true);
    appState.apiUrl=apiUrl;
    localStorage.setItem(STORAGE_KEYS.apiUrl,apiUrl);
    const data=await apiRequest({action:'login',username,password});
    appState.token=data.token;
    appState.user=data.user;
    appState.menuAccess=data.menu_access||[];
    localStorage.setItem(STORAGE_KEYS.token,appState.token);
    localStorage.setItem(STORAGE_KEYS.user,JSON.stringify(appState.user));
    showDashboardPage();
    showToast('Login berhasil.','success');
    setTimeout(async function(){
      try{await renderDashboard();setupPwaManifest();startRealtimeSync();}
      catch(err){showToast('Login berhasil, tetapi sinkronisasi awal perlu diulang: '+(err&&err.message?err.message:err),'warning');}
    },30);
  }catch(e){showToast(e&&e.message?e.message:String(e),'error')}
  finally{showLoading(false)}
}
async function logout(){showLoading(true);try{if(appState.token)await apiRequest({action:'logout',token:appState.token}).catch(()=>{})}finally{appState.token='';appState.user=null;appState.menuAccess=[];localStorage.removeItem(STORAGE_KEYS.token);localStorage.removeItem(STORAGE_KEYS.user);showLoginPage();showLoading(false);showToast('Logout berhasil.','success')}}
async function verifySession(){
  try{
    showLoading(true);
    const data=await apiRequest({action:'verifySession',token:appState.token});
    appState.user=data.user;
    appState.menuAccess=data.menu_access||[];
    localStorage.setItem(STORAGE_KEYS.user,JSON.stringify(appState.user));
    showDashboardPage();
    setTimeout(async function(){try{await renderDashboard();setupPwaManifest();startRealtimeSync();}catch(err){console.warn(err)}},30);
  }catch(e){
    localStorage.removeItem(STORAGE_KEYS.token);localStorage.removeItem(STORAGE_KEYS.user);
    appState.token='';appState.user=null;appState.menuAccess=[];
    showLoginPage();showToast('Sesi berakhir. Login ulang.','warning')
  }finally{showLoading(false)}
}
function showLoginPage(){el('loginPage').classList.remove('hidden');el('dashboardPage').classList.add('hidden');el('modulePage').classList.add('hidden');el('bottomNav').classList.add('hidden')}
function showDashboardPage(){el('loginPage').classList.add('hidden');el('dashboardPage').classList.remove('hidden');el('modulePage').classList.add('hidden');el('bottomNav').classList.remove('hidden');setBottomActive('home')}
function showModulePage(){el('loginPage').classList.add('hidden');el('dashboardPage').classList.add('hidden');el('modulePage').classList.remove('hidden');el('bottomNav').classList.remove('hidden')}
function setModuleContent(title,html){el('moduleTitle').textContent=title||'Modul';el('moduleBody').innerHTML=html||'';showModulePage();window.scrollTo({top:0,behavior:'smooth'})}
function setBottomActive(key){document.querySelectorAll('.bottom-item').forEach(i=>i.classList.remove('active'));const id={home:'bottomHome',data:'bottomData',scan:'bottomScan',activity:'bottomActivity',profile:'bottomProfile'}[key]||'bottomHome';el(id).classList.add('active')}
async function renderDashboard(){await loadAppBranding();const user=appState.user||{},role=user.role||'';el('avatarIcon').innerHTML=user.photo_url?'':(ROLE_AVATAR[role]||'👤');el('userNameText').textContent=user.name||'Pengguna';el('userRoleText').textContent=user.role_label||role||'Role';const title={super_admin:'Dashboard Super Admin',admin:'Dashboard Admin Prakerin',humas:'Dashboard Waka Humas',kurikulum:'Dashboard Waka Kurikulum',kepala_sekolah:'Dashboard Kepala Sekolah',guru:'Dashboard Guru Pembimbing',wali_kelas:'Dashboard Wali Kelas',siswa:'Dashboard Siswa Prakerin',industri:'Dashboard Pembimbing Industri',pembimbing_dudi:'Dashboard Pembimbing Dunia Usaha',orang_tua:'Dashboard Orang Tua'}[role]||'Dashboard SI-PRAKERIN';el('dashboardTitle').textContent=title;el('dashboardDesc').textContent='Pantau penempatan, presensi QR, jurnal, monitoring, nilai, sertifikat, laporan, dan file upload sesuai hak akses.';renderQuickMenu();await loadDashboardStats(false)}
async function loadDashboardStats(forceRefresh){try{let old=el('dashboardDynamicStats');if(old)old.remove();const section=document.querySelector('#dashboardPage .dashboard-layout'),loading=document.createElement('div');loading.id='dashboardDynamicStats';loading.className='dashboard-loading';loading.innerHTML='

Memuat Statistik
Mengambil data dashboard dari database...';section.insertBefore(loading,document.querySelector('#dashboardPage .section'));const data=await apiRequest({action:'getDashboardStats',token:appState.token,force_refresh:forceRefresh?'true':'false'});appState.dashboardData=data;renderDashboardStats(data)}catch(e){const old=el('dashboardDynamicStats');if(old)old.innerHTML='

Dashboard Tidak Dapat Dimuat
'+escapeHtml(e.message)+''}}
function renderDashboardStats(data){const dynamic=el('dashboardDynamicStats');if(!dynamic)return;const c=data.cards||{};el('statStudents').textContent=c.students||0;el('statIndustries').textContent=c.industries||0;el('statJournals').textContent=c.journals||0;dynamic.className='';dynamic.innerHTML='
'+[['🎒','Siswa',c.students],['🏢','DU/DI',c.industries],['📍','Penempatan',c.placements],['✅','Presensi',c.attendance],['📝','Jurnal',c.journals],['🚗','Monitoring',c.monitoring],['📊','Nilai',c.assessments],['🏅','Sertifikat',c.certificates]].map(x=>renderDashboardCard(x[0],x[1],x[2]||0)).join('')+'


Grafik Ringkas
Refresh'+renderBarChart('Presensi',(data.charts&&data.charts.attendance_chart)||[])+renderBarChart('Jurnal',(data.charts&&data.charts.journal_chart)||[])+renderBarChart('Penilaian',(data.charts&&data.charts.assessment_chart)||[])+'


Aktivitas Terbaru'+renderRecent((data.recent&&data.recent.journals)||[])+''}
function renderDashboardCard(i,l,v){return '

'+escapeHtml(i)+'
'+escapeHtml(v)+'
'+escapeHtml(l)+''}
function renderBarChart(title,items){const max=Math.max(...(items||[]).map(i=>Number(i.value||0)),1);return '

'+escapeHtml(title)+''+((items||[]).map(i=>{const val=Number(i.value||0),w=Math.round(val/max*100);return '

'+escapeHtml(i.label||'-')+''+val+'

'}).join('')||'
Belum ada data.')+''}
function renderRecent(items){return items.length?'
'+items.map(i=>'

'+escapeHtml((i.student&&i.student.name)||i.student_id||'-')+'
'+escapeHtml(i.journal_date||i.date||'-')+' · '+escapeHtml(i.status||'-')+'
'+escapeHtml(shortText(i.activity||i.notes||'-',90))+'').join('')+'':'
Belum ada aktivitas.'}
function renderQuickMenu(){const priority=['students','teachers','industries','placements','my_placement','scan_qr','qr_sessions','attendance','my_attendance','journals','my_journals','journal_validation','monitoring','assessments','my_assessment','certificates','my_certificate','reports','uploads','backup'];const items=priority.filter(k=>appState.menuAccess.includes(k)).slice(0,8);el('quickMenuGrid').innerHTML=items.map(k=>{const it=MENU_CATALOG[k]||{label:k,icon:'📦'};return '

'+escapeHtml(it.icon)+'
'+escapeHtml(it.label)+''}).join('')||'

Belum Ada Menu
Hak akses menu belum tersedia.'}
function openModule(k){appState.currentModule=k;if(k==='dashboard')return showDashboardPage();if(k==='profile')return openProfileModule();if(k==='settings')return openSettingsModule();if(k==='uploads')return openUploadModule();if(k==='scan_qr')return openScanQrModule();if(k==='qr_sessions')return openQrSessionModule();if(['attendance','my_attendance','attendance_validation'].includes(k))return openAttendanceModule(k);if(['journals','my_journals','journal_validation'].includes(k))return openJournalModule(k);if(k==='monitoring')return openMonitoringModule();if(['my_students','my_placements','my_industries','industry_students','my_class_students'].includes(k))return openSimpleListModule(k);if(['assessments','my_assessment','industry_assessment'].includes(k))return openAssessmentModule(k);if(['certificates','my_certificate'].includes(k))return openCertificateModule(k);if(['reports','documents'].includes(k))return openReportModule();if(k==='backup')return openToolsModule();if(k==='my_placement')return openMyPlacementModule();if(['majors','classes','students','teachers','industries','industry_mentors','periods','teacher_industry_assignments','placements','users'].includes(k))return openCrudModule(k);const it=MENU_CATALOG[k]||{title:k,icon:'🚧',text:'Modul sedang disiapkan.'};setModuleContent(it.title,'

'+it.icon+'
'+escapeHtml(it.label||it.title)+'
'+escapeHtml(it.text||'')+'')}
function openAllMenuModule(group){const groupMap={data:['majors','classes','students','teachers','industries','industry_mentors','periods','teacher_industry_assignments','placements','my_students','my_industries','my_placements','my_class_students','industry_students'],activity:['qr_sessions','scan_qr','attendance','my_attendance','attendance_validation','journals','my_journals','journal_validation','monitoring','assessments','my_assessment','industry_assessment','certificates','my_certificate','reports','uploads','backup']};const allowed=(group&&groupMap[group]?groupMap[group]:appState.menuAccess).filter(k=>appState.menuAccess.includes(k));setModuleContent('Semua Menu','

Semua Menu
Pilih menu sesuai hak akses.
'+allowed.map(k=>{const it=MENU_CATALOG[k]||{label:k,icon:'📦'};return '

'+escapeHtml(it.icon)+'
'+escapeHtml(it.label)+''}).join('')+'');setBottomActive(group==='data'?'data':'activity')}

async function loadAppBranding(){try{const d=await apiRequest({action:'getAppBranding'});appState.branding=d||{};applyAppBranding();setupPwaManifest()}catch(e){}}
function applyAppBranding(){const b=appState.branding||{},url=b.app_logo_url||b.school_logo_url||b.app_icon_url||'';if(url){document.querySelectorAll('.login-logo').forEach(x=>x.innerHTML='')}const title=document.querySelector('.login-title');if(title&&b.school_name)title.textContent='SI-PRAKERIN '+b.school_name}

