    const s=appState.settings,b=appState.branding||{};
    const imgHelp='Mendukung semua format gambar umum: JPG, JPEG, PNG, WEBP, GIF, SVG, ICO, BMP, AVIF, HEIC/HEIF. Format raster akan dikompres otomatis bila browser mendukung. Database hanya menyimpan URL/metadata Google Drive.';
