    );
    window.setSelectValue('set_wa_enabled',String(s.wa_enabled||'false'));
    window.setSelectValue('set_upload_public_access',String(s.upload_public_access||'true'));
    window.setSelectValue('set_pwa_enabled',String(s.pwa_enabled||'true'));
    setBottomActive('data');
  }catch(e){showToast(e.message,'error')}finally{showLoading(false)}
}

function openBrandingModule(){return openSettingsModule()}
function setupPwaManifest(){try{const b=appState.branding||{},s=appState.settings||{},name='SI-PRAKERIN '+(s.school_name||b.school_name||'SMK'),icon=b.app_icon_url||b.app_logo_url||b.school_logo_url||'';const manifest={name:name,short_name:'SI-PRAKERIN',start_url:location.href.split('#')[0],display:'standalone',background_color:'#f4f8ff',theme_color:s.app_theme_color||'#0b6edc',orientation:'portrait-primary',icons:icon?[{src:icon,sizes:'192x192',type:'image/png'},{src:icon,sizes:'512x512',type:'image/png'}]:[]};const link=el('appManifestLink');if(link)link.href='data:application/manifest+json;charset=utf-8,'+encodeURIComponent(JSON.stringify(manifest));document.querySelector('meta[name="theme-color"]')?.setAttribute('content',manifest.theme_color)}catch(e){}}

