'+(related?renderObjectAsText(related):'Belum ada data terkait.')+'');setBottomActive('profile')}catch(e){showToast(e.message,'error')}finally{showLoading(false)}}
async function submitProfileForm(){try{const newPass=getInputValue('profileNewPasswordInput'),confirmPass=getInputValue('profileConfirmPasswordInput');if(newPass&&newPass!==confirmPass)return showToast('Konfirmasi password baru tidak sama.','error');showLoading(true);let photoUrl='';const input=el('profilePhotoInput');if(input&&input.files&&input.files.length){const prepared=await prepareFileForUpload(input.files[0],900,.72);const up=await apiRequest({action:'uploadFile',token:appState.token,file_name:prepared.fileName,mime_type:prepared.mimeType,file_size:prepared.size,base64_data:prepared.base64Data,module:'profile',related_id:(appState.user&&appState.user.id)||'',description:'Foto profil pengguna'});photoUrl=up.thumbnail_url||up.file_url||''}const data=await apiRequest({action:'updateMyProfile',token:appState.token,name:getInputValue('profileNameInput'),username:getInputValue('profileUsernameInput'),email:getInputValue('profileEmailInput'),phone:getInputValue('profilePhoneInput'),photo_url:photoUrl||undefined,current_password:getInputValue('profileCurrentPasswordInput'),new_password:newPass});appState.user=data.user;appState.menuAccess=data.menu_access||appState.menuAccess;localStorage.setItem(STORAGE_KEYS.user,JSON.stringify(appState.user));showToast('Profil berhasil diperbarui.','success');await renderDashboard();openProfileModule()}catch(e){showToast(e.message,'error')}finally{showLoading(false)}}

async function openMyPlacementModule(){try{showLoading(true);const d=await apiRequest({action:'getMyPlacement',token:appState.token});const item=d.placement;setModuleContent('Prakerin Saya',item?'

Data Penempatan Prakerin
Nama: '+escapeHtml((item.student&&item.student.name)||'-')+'
