async function renderCrudFields(cfg){let html='';for(const field of cfg.fields)html+=await renderCrudField(field);el('crudFieldsBox').innerHTML=html}
async function renderCrudField(field){const id='crud_'+field.name,req=field.required?'required':'';if(field.type==='textarea')return '
'+escapeHtml(field.label)+'';if(field.type==='select')return '
'+escapeHtml(field.label)+'- Pilih -'+(field.options||[]).map(o=>''+escapeHtml(o[1])+'').join('')+'';if(field.type==='relation'){const rows=await loadRelationData(field.source);return '
'+escapeHtml(field.label)+'- Pilih -'+rows.map(r=>''+escapeHtml(r[field.labelField]||r.name||r.id)+' ('+escapeHtml(r.id)+')').join('')+''}return '
'+escapeHtml(field.label)+''}
async function loadRelationData(src){if(relationCache[src])return relationCache[src];try{const d=await apiRequest({action:'getDropdownData',token:appState.token,modules:src});Object.keys(d||{}).forEach(k=>relationCache[k]=d[k]||[]);relationCache[src]=d[src]||[];return relationCache[src]}catch(e){relationCache[src]=[];return[]}}
