function toggleSelectAllCrud(checked){document.querySelectorAll('.crud-check').forEach(x=>x.checked=checked)}
function getSelectedCrudIds(){return Array.from(document.querySelectorAll('.crud-check:checked')).map(x=>x.value).filter(Boolean)}
function renderCell(item,c){if(c.includes('status'))return renderStatusBadge(item[c]||'-');return escapeHtml(resolveDisplayValue(item,c))}
function resolveDisplayValue(item,c){if(c==='class_id'&&item.class)return item.class.class_name;if(c==='major_id'&&item.major)return item.major.major_name;if(c==='teacher_id'&&item.teacher)return item.teacher.name;if(c==='homeroom_teacher_id'&&item.homeroom_teacher)return item.homeroom_teacher.name;if(c==='industry_id'&&item.industry)return item.industry.name;if(c==='student_id'&&item.student)return item.student.name;if(c==='period_id'&&item.period)return item.period.period_name;if(c==='industry_mentor_id'&&item.industry_mentor)return item.industry_mentor.name;return item[c]??''}
