function fillCrudEditForm(key,id){const cfg=CRUD_CONFIG[key],item=currentCrudItems.find(r=>String(r.id)===String(id));if(!item)return showToast('Data tidak ditemukan.','error');currentCrudEditId=id;toggleCrudForm(true);cfg.fields.forEach(field=>{const x=el('crud_'+field.name);if(x&&item[field.name]!=null)x.value=item[field.name]});const t=document.querySelector('#crudFormBox .crud-form-title');if(t)t.textContent='✏️ Edit '+cfg.title;showToast('Mode edit aktif: '+id,'success')}
