function dataUrlToBlob(dataUrl){const parts=String(dataUrl).split(','),meta=parts[0]||'',b64=parts[1]||'',mime=(meta.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';const bin=atob(b64);const arr=new Uint8Array(bin.length);for(let i=0;i{const reader=new FileReader();reader.onerror=()=>reject(new Error('Gambar gagal dibaca.'));reader.onload=e=>{const img=new Image();img.onerror=()=>reject(new Error('Format gambar tidak valid.'));img.onload=()=>{let w=img.width,h=img.height;if(w>h&&w>maxSize){h=Math.round(h*maxSize/w);w=maxSize}else if(h>=w&&h>maxSize){w=Math.round(w*maxSize/h);h=maxSize}const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);const out=canvas.toDataURL('image/jpeg',quality);const blob=dataUrlToBlob(out);const base=(file.name||'gambar').replace(/\.[^.]+$/,'');resolve({fileName:base+'-compressed.jpg',mimeType:'image/jpeg',size:blob.size,base64Data:out})};img.src=e.target.result};reader.readAsDataURL(file)})}

function readFileAsBase64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=e=>resolve(e.target.result);r.onerror=()=>reject(new Error('File gagal dibaca.'));r.readAsDataURL(file)})}
