function formatFileSize(size){size=Number(size||0);if(size<1024)return size+' B';if(size<1024*1024)return Math.round(size/1024)+' KB';return(size/(1024*1024)).toFixed(2)+' MB'}
function showLoading(show){el('loadingOverlay').classList.toggle('hidden',!show)}
function showToast(msg,type){const box=el('toastBox');box.textContent=msg||'';box.className='toast show '+(type||'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.className='toast',3200)}
function escapeHtml(v){return String(v??'').replace(/&/g,'&').replace(//g,'>').replace(/"/g,'"').replace(/'/g,''')}
function setSelectValue(id,value){
  const x=el(id);
  if(!x)return false;
  const val=String(value==null?'':value);
  if(x.tagName && x.tagName.toLowerCase()==='select'){
    let found=false;
    Array.from(x.options||[]).forEach(o=>{if(String(o.value)===val)found=true});
    if(!found && val!==''){
      const opt=document.createElement('option');
      opt.value=val;
      opt.textContent=val;
      x.appendChild(opt);
    }
  }
  x.value=val;
  try{x.dispatchEvent(new Event('change',{bubbles:true}))}catch(e){}
  return true;
}

function getInputValue(id){const x=el(id);return x?x.value:''}
function shortText(t,n){t=String(t||'');return t.length<=n?t:t.substring(0,n)+'...'}
function renderStatusBadge(status){const raw=String(status||'-'),v=raw.toLowerCase();let cls='badge';if(['active','valid','published','issued','final','completed','h','hadir','kompeten','success','sent'].includes(v))cls+=' success';else if(['draft','pending','revision','planned','i','s'].includes(v))cls+=' warning';else if(['inactive','cancelled','rejected','failed','a','belum_kompeten'].includes(v))cls+=' danger';else cls+=' muted';return ''+escapeHtml(raw)+''}
function registerLightServiceWorker(){try{if('serviceWorker' in navigator){const code='self.addEventListener(\'install\',e=>self.skipWaiting());self.addEventListener(\'activate\',e=>self.clients.claim());self.addEventListener(\'fetch\',e=>{});';const url=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));navigator.serviceWorker.register(url).catch(()=>{});}}catch(e){}}
document.addEventListener('DOMContentLoaded',()=>setTimeout(registerLightServiceWorker,1500));
