    if(appState.currentModule&&['attendance','my_attendance','attendance_validation'].indexOf(appState.currentModule)>=0&&document.getElementById('attendanceListBox'))await loadAttendance(appState.currentModule,spAttendancePageState.page,true);
    if(spSimplePageState.key&&document.getElementById('simpleListBox'))await loadSimpleList(spSimplePageState.key,spSimplePageState.page,true);
    if(appState.currentModule==='qr_sessions'&&document.getElementById('qrSessionListBox'))await loadQrSessions(finalQrPageState.page,true);
    if(appState.currentModule==='monitoring'&&document.getElementById('monitoringListBox'))await loadMonitoring(finalMonitoringPageState.page,true);
    if(['assessments','my_assessment','industry_assessment'].indexOf(appState.currentModule)>=0&&document.getElementById('assessmentListBox'))await loadAssessments(appState.currentModule,finalAssessmentPageState.page,true);
    if(['certificates','my_certificate'].indexOf(appState.currentModule)>=0&&document.getElementById('certificateListBox'))await loadCertificates(finalCertificatePageState.page,true);
    if(appState.currentModule==='uploads'&&document.getElementById('uploadedFilesBox'))await loadUploadedFiles();
    if(!document.getElementById('modulePage')||document.getElementById('modulePage').classList.contains('hidden'))await loadDashboardStats(true);
  }catch(e){try{console.warn('Auto-sync refresh warning:',e&&e.message?e.message:e)}catch(_){}}
}

(function(){
  'use strict';
  function byId(id){return document.getElementById(id)}
  if(typeof window.el!=='function') window.el=byId;
  if(typeof window.escapeHtml!=='function') window.escapeHtml=function(v){return String(v??'').replace(/&/g,'&').replace(//g,'>').replace(/"/g,'"').replace(/'/g,''')};
  if(typeof window.getInputValue!=='function') window.getInputValue=function(id){var x=byId(id);return x?x.value:''};
  if(typeof window.showLoading!=='function') window.showLoading=function(show){var x=byId('loadingOverlay');if(x)x.classList.toggle('hidden',!show)};
  if(typeof window.showToast!=='function') window.showToast=function(msg,type){var box=byId('toastBox');if(!box){alert(msg||'');return;}box.textContent=msg||'';box.className='toast show '+(type||'');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(function(){box.className='toast'},3200)};
  var oldApi=window.apiRequest;
  if(typeof oldApi==='function'&&!oldApi.__fastPatched){
    window.apiRequest=async function(payload){
      var apiUrl=(window.appState&&appState.apiUrl)||localStorage.getItem('siprakerin_api_url')||(window.APP_FRONTEND&&APP_FRONTEND.defaultApiUrl)||'';
      if(!apiUrl)throw new Error('URL Apps Script belum diisi.');
      var controller=null,timer=null;
      try{
        if(window.AbortController){controller=new AbortController();timer=setTimeout(function(){try{controller.abort()}catch(e){}},25000)}
        var res=await fetch(apiUrl,{method:'POST',mode:'cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload||{}),signal:controller?controller.signal:undefined});
        var json=await res.json();
        if(!json.success)throw new Error(json.message||'Request gagal.');
        return json.data;
      }catch(e){if(e&&e.name==='AbortError')throw new Error('Koneksi lambat atau server tidak merespons. Coba ulangi.');throw e;}finally{if(timer)clearTimeout(timer)}
    };
    window.apiRequest.__fastPatched=true;
  }
  function bindLoginSafely(){
    var overlay=byId('loadingOverlay'); if(overlay)overlay.classList.add('hidden');
    var form=byId('loginForm'); if(!form||form.__safeLoginBound)return;
    form.__safeLoginBound=true;
    var btn=form.querySelector('button[type="submit"], .btn-primary');
    if(btn){btn.disabled=false;btn.style.pointerEvents='auto';btn.setAttribute('type','submit');}
    form.addEventListener('submit',function(ev){ev.preventDefault();if(typeof window.login==='function')window.login();else window.showToast('Script login belum termuat sempurna. Muat ulang halaman.','error');});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bindLoginSafely);else bindLoginSafely();
  window.addEventListener('pageshow',bindLoginSafely);
})();

(function(){
  'use strict';
  function byId(id){return document.getElementById(id)}
  function safeToast(msg,type){
    var box=byId('toastBox');
    if(!box){ try{console.log(msg||'')}catch(e){} return; }
    box.textContent=msg||'';
    box.className='toast show '+(type||'');
    clearTimeout(window.__finalToastTimer);
    window.__finalToastTimer=setTimeout(function(){box.className='toast'},2800);
  }
  function safeLoading(show){var x=byId('loadingOverlay');if(x)x.classList.toggle('hidden',!show)}
  window.showLoading = window.showLoading || safeLoading;
  window.showToast = window.showToast || safeToast;
  window.showDashboardPage = function(){
    var login=byId('loginPage'), dash=byId('dashboardPage'), mod=byId('modulePage'), nav=byId('bottomNav');
    if(login)login.classList.add('hidden');
    if(dash)dash.classList.remove('hidden');
    if(mod)mod.classList.add('hidden');
    if(nav)nav.classList.remove('hidden');
    try{ if(typeof setBottomActive==='function') setBottomActive('home'); }catch(e){}
  };
  window.showLoginPage = window.showLoginPage || function(){
    var login=byId('loginPage'), dash=byId('dashboardPage'), mod=byId('modulePage'), nav=byId('bottomNav');
    if(login)login.classList.remove('hidden');
    if(dash)dash.classList.add('hidden');
    if(mod)mod.classList.add('hidden');
    if(nav)nav.classList.add('hidden');
  };
  var realStart = window.startRealtimeSync;
  window.startRealtimeSync = function(){
    try{
      var token='';
      try{ token=(typeof appState!=='undefined'&&appState&&appState.token)||''; }catch(e){}
      token = token || localStorage.getItem('siprakerin_token') || '';
      if(!token) return;
      if(window.__siprakerinRealtimeActive) return;
      window.__siprakerinRealtimeActive=true;
      if(typeof realStart==='function') return realStart();
    }catch(e){window.__siprakerinRealtimeActive=false;}
  };
  var realStop = window.stopRealtimeSync;
  window.stopRealtimeSync = function(){
    window.__siprakerinRealtimeActive=false;
    try{ if(typeof spRealtimeTimer!=='undefined' && spRealtimeTimer){clearInterval(spRealtimeTimer);spRealtimeTimer=null;} }catch(e){}
    try{ if(typeof realStop==='function') realStop(); }catch(e){}
  };
  function bind(){
    safeLoading(false);
    var form=byId('loginForm');
    if(!form) return;
    var btn=form.querySelector('button[type="submit"],button.btn-primary,.btn-primary');
    if(btn){btn.disabled=false;btn.style.pointerEvents='auto';btn.style.cursor='pointer';btn.setAttribute('type','submit');}
    if(form.__finalNoRecursionBound) return;
    form.__finalNoRecursionBound=true;
    form.addEventListener('submit',function(ev){
      ev.preventDefault();ev.stopPropagation();
      try{
        if(typeof window.login==='function') return window.login();
        if(typeof login==='function') return login();
        safeToast('Fungsi login belum siap. Refresh halaman lalu coba lagi.','error');
      }catch(e){safeLoading(false);safeToast((e&&e.message)?e.message:String(e),'error')}
    },true);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
  window.addEventListener('pageshow',bind);
})();

/* FINAL SAVE / BRANDING UPLOAD FIX - Generated 2026-06-05
   Fixes: tombol Simpan Pengaturan, upload logo/icon/favicon, and global save aliases. */
(function(){
  'use strict';
  function byId(id){return document.getElementById(id);}
  function toast(msg,type){
    try{ if(typeof window.showToast==='function') return window.showToast(msg,type||''); }catch(e){}
    var box=byId('toastBox');
    if(box){ box.textContent=msg||''; box.className='toast show '+(type||''); setTimeout(function(){box.className='toast'},2800); }
    else { try{ console.log(msg||''); }catch(e){} }
  }
  function loading(show){ try{ if(typeof window.showLoading==='function') return window.showLoading(!!show); }catch(e){} var x=byId('loadingOverlay'); if(x)x.classList.toggle('hidden',!show); }
  function val(id){var x=byId(id); return x?String(x.value||'').trim():'';}
  function fileExt(name){var s=String(name||''); return s.indexOf('.')>=0?s.split('.').pop().toLowerCase():'';}
  async function prepare(file,max,quality){
    if(typeof window.prepareFileForUpload==='function') return await window.prepareFileForUpload(file,max||1200,quality||0.75);
    if(!file) throw new Error('File tidak ditemukan.');
    var base64 = await new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(e){resolve(e.target.result)};r.onerror=function(){reject(new Error('File gagal dibaca.'))};r.readAsDataURL(file);});
    return {fileName:file.name,mimeType:file.type||'application/octet-stream',size:file.size||0,base64Data:base64};
  }
  function getAuthToken(){
    var t='';
    try{ if(typeof appState!=='undefined' && appState && appState.token) t=String(appState.token||''); }catch(e){}
    if(!t){ try{ t=String(localStorage.getItem('siprakerin_token')||''); }catch(e){} }
    if(t){ try{ if(typeof appState!=='undefined' && appState){ appState.token=t; window.appState=appState; } }catch(e){} }
    return t;
  }
  function ensureActiveSession(){
    var t=getAuthToken();
    if(!t) throw new Error('Sesi login tidak ditemukan. Silakan login ulang.');
    return t;
  }
  async function uploadFromInput(inputId,moduleName,relatedId,description,preferDirect){
    var input=byId(inputId);
    if(!input || !input.files || !input.files.length) return null;
    var file=input.files[0];
    var prepared=await prepare(file,900,0.78);
    var data=await apiRequest({
      action:'uploadFile',
      token:getAuthToken(),
      file_name:prepared.fileName,
      mime_type:prepared.mimeType,
      file_size:prepared.size,
      base64_data:prepared.base64Data,
      module:moduleName||'settings',
      related_id:relatedId||moduleName||'settings',
      description:description||'Upload file pengaturan aplikasi'
    });
    var mime=String(data.mime_type||prepared.mimeType||'');
    var ext=String(data.file_extension||fileExt(data.file_name||prepared.fileName||file.name));
    var displayUrl=data.thumbnail_url||data.download_url||data.file_url||'';
    var directUrl=data.download_url||data.thumbnail_url||data.file_url||'';
    return {row:data,url:preferDirect?directUrl:displayUrl,directUrl:directUrl,displayUrl:displayUrl,mimeType:mime,extension:ext};
  }
  window.submitSettingsForm = async function submitSettingsFormFixed(){
    if(window.__siprakerinSavingSettings) return;
    window.__siprakerinSavingSettings=true;
    try{
      var authToken=ensureActiveSession();
      loading(true);
      var settings={
        school_name:val('set_school_name'),
        school_address:val('set_school_address'),
        items_per_page:val('set_items_per_page')||'10',
        qr_expire_minutes:val('set_qr_expire_minutes')||'30',
        wa_enabled:val('set_wa_enabled')||'false',
        wa_provider:val('set_wa_provider')||'WAPLUS',
        wa_api_url:val('set_wa_api_url'),
        wa_api_key:val('set_wa_api_key'),
        wa_sender_number:val('set_wa_sender_number'),
        drive_upload_root_folder_id:val('set_drive_upload_root_folder_id'),
        upload_public_access:val('set_upload_public_access')||'true',
        pwa_enabled:val('set_pwa_enabled')||'true',
        app_theme_color:val('set_app_theme_color')||'#0b6edc',
        favicon_url:val('set_favicon_url')
      };
      var logo=await uploadFromInput('brandLogoInput','branding','app_logo','Logo aplikasi / login',false);
      if(logo && logo.url){ settings.app_logo_url=logo.url; }
      var schoolIcon=await uploadFromInput('brandSchoolLogoInput','branding','school_icon','Icon sekolah / PWA',false);
      if(schoolIcon && schoolIcon.url){ settings.school_logo_url=schoolIcon.url; settings.app_icon_url=schoolIcon.url; }
      var favicon=await uploadFromInput('brandFaviconInput','branding','favicon','Favicon aplikasi',true);
      if(favicon && favicon.url){
        settings.favicon_url=favicon.url;
        settings.favicon_mime_type=favicon.mimeType||'';
        settings.favicon_file_extension=favicon.extension||'';
      }
      var result=await apiRequest({action:'updateSettings',token:authToken,settings:settings});
      appState.settings=(result&&result.settings)||Object.assign({},appState.settings||{},settings);
      appState.branding=(result&&result.branding)||appState.settings;
      try{ if(typeof applyFavicon==='function') applyFavicon(appState.branding.favicon_url||appState.settings.favicon_url||settings.favicon_url||''); }catch(e){}
      try{ if(typeof applyAppBranding==='function') applyAppBranding(); }catch(e){}
      try{ if(typeof setupPwaManifest==='function') setupPwaManifest(); }catch(e){}
      try{ localStorage.setItem('siprakerin_settings_cache', JSON.stringify({time:Date.now(),settings:appState.settings,branding:appState.branding})); }catch(e){}
      toast('Pengaturan berhasil disimpan. Logo/icon/favicon juga sudah diproses bila dipilih.','success');
      try{ if(typeof openSettingsModule==='function') await openSettingsModule(); }catch(e){}
    }catch(e){
      toast((e&&e.message)?e.message:String(e),'error');
    }finally{
      window.__siprakerinSavingSettings=false;
      loading(false);
    }
  };
  window.saveSettings = window.submitSettingsForm;
  window.submitBrandingForm = window.submitSettingsForm;
  // Event-delegation fallback: even if inline onclick is stripped by a template engine, save still works.
  document.addEventListener('click',function(ev){
    var t=ev.target && ev.target.closest ? ev.target.closest('button') : null;
    if(!t) return;
    var txt=(t.textContent||'').toLowerCase();
    var oc=String(t.getAttribute('onclick')||'');
    if(oc.indexOf('submitSettingsForm')>=0 || (txt.indexOf('simpan pengaturan')>=0 && byId('set_school_name'))){
      ev.preventDefault(); ev.stopPropagation(); window.submitSettingsForm();
    }
  },true);
})();

/* FINAL SESSION / SAVE BUTTON SAFETY PATCH */
(function(){
  'use strict';
  try{ if(typeof appState!=='undefined' && appState){ window.appState=appState; if(!appState.token){ var tok=localStorage.getItem('siprakerin_token')||''; if(tok) appState.token=tok; } } }catch(e){}
  function byId(id){return document.getElementById(id)}
  function toast(msg,type){try{if(typeof window.showToast==='function')return window.showToast(msg,type||'error')}catch(e){} var box=byId('toastBox'); if(box){box.textContent=msg; box.className='toast show '+(type||'error'); setTimeout(function(){box.className='toast'},3000);} }
  function getTok(){var t=''; try{ if(typeof appState!=='undefined'&&appState&&appState.token)t=appState.token; }catch(e){} if(!t){try{t=localStorage.getItem('siprakerin_token')||'';}catch(e){}} if(t){try{appState.token=t; window.appState=appState;}catch(e){}} return t;}
  document.addEventListener('click',function(ev){
    var b=ev.target&&ev.target.closest?ev.target.closest('button'):null; if(!b)return;
    var txt=(b.textContent||'').toLowerCase();
    if(txt.indexOf('simpan pengaturan')>=0){
      getTok();
      if(!getTok()){ev.preventDefault();ev.stopPropagation();toast('Sesi login tidak ditemukan. Silakan login ulang.','error');return;}
      if(typeof window.submitSettingsForm==='function'){ev.preventDefault();ev.stopPropagation();window.submitSettingsForm();}
    }
  },true);
})();
